using Unity.Netcode;
using UnityEngine;

// Author : Baptiste Vu Liem
namespace Com.IsartDigital.GoobyrFPS.Net
{
    /// <summary>
    /// The network prefabs the host spawns at runtime, generated by the prefab builder
    /// (<c>Resources/NetPrefabs</c>). The same prefabs are listed in the NetworkManager's prefab list.
    /// </summary>
    [CreateAssetMenu(menuName = "Goobyr/Net Prefabs")]
    public class NetPrefabs : ScriptableObject
    {
        public NetworkObject mapSession;
        public NetworkObject playerAvatar;
        public NetworkObject npc;
        public NetworkObject itemPickup;
        public NetworkObject proof;
        public NetworkObject rocket;
        public NetworkObject thrown;
        public NetworkObject vehicle;

        private static NetPrefabs _instance;
        public static NetPrefabs Instance => _instance != null ? _instance : _instance = Resources.Load<NetPrefabs>("NetPrefabs");
    }
}
